// aim.cpp
// Projects entity head positions to screen space and returns a smoothed
// crosshair delta toward the best target inside a screen-space cone.
//
// Engine-agnostic: the caller supplies the view-projection matrix, viewport
// size and entity list from its own scene. The output is a pixel delta. What
// the caller does with it (move the camera, draw a guide, score the player)
// is up to the caller.

#include <cmath>
#include <cstdint>
#include <limits>
#include <vector>

namespace aim {

struct Vec2 { float x = 0, y = 0; };
struct Vec3 { float x = 0, y = 0, z = 0; };

// Row-major 4x4, clip = M * [x y z 1]^T.
// If your engine stores column-major (e.g. GLM), pass glm::transpose(vp)
// or flip the indexing in worldToScreen.
struct Mat4 { float m[16]; };

struct Entity {
    int32_t id = -1;
    Vec3    head;          // world-space head position
    bool    active = true; // skip dead/hidden/disabled targets
};

struct Config {
    float fovRadiusPx   = 240.0f; // cone radius around screen center
    float smoothRate    = 12.0f;  // higher = snappier (1/s, frame-rate independent)
    float maxStepPx     = 60.0f;  // per-frame clamp on delta magnitude, <=0 disables
    float stickyBonusPx = 30.0f;  // hysteresis: current target gets this much
                                  // extra radius / priority to prevent flicker
};

// Returns false if the point is behind the camera or outside the clip volume.
bool worldToScreen(const Mat4& vp, const Vec3& p, float viewW, float viewH, Vec2& out)
{
    const float* m = vp.m;
    const float cx = m[0]  * p.x + m[1]  * p.y + m[2]  * p.z + m[3];
    const float cy = m[4]  * p.x + m[5]  * p.y + m[6]  * p.z + m[7];
    const float cz = m[8]  * p.x + m[9]  * p.y + m[10] * p.z + m[11];
    const float cw = m[12] * p.x + m[13] * p.y + m[14] * p.z + m[15];

    if (cw < 1e-4f) return false; // behind or on the near plane

    const float nx = cx / cw;
    const float ny = cy / cw;
    const float nz = cz / cw;
    if (nx < -1.f || nx > 1.f || ny < -1.f || ny > 1.f || nz < -1.f || nz > 1.f)
        return false;

    out.x = (nx * 0.5f + 0.5f) * viewW;
    out.y = (1.0f - (ny * 0.5f + 0.5f)) * viewH; // screen y grows downward
    return true;
}

class Tracker {
public:
    explicit Tracker(Config cfg = {}) : cfg_(cfg) {}

    void setConfig(const Config& cfg) { cfg_ = cfg; }
    const Config& config() const { return cfg_; }

    int32_t currentTarget() const { return targetId_; }
    void reset() { targetId_ = -1; }

    // dt in seconds. Returns the pixel delta to apply this frame
    // ({0,0} when no target is in the cone).
    Vec2 update(const std::vector<Entity>& entities, const Mat4& vp,
                float viewW, float viewH, float dt)
    {
        const Vec2 center{ viewW * 0.5f, viewH * 0.5f };

        int32_t bestId = -1;
        Vec2    bestOffset{};
        float   bestScore = std::numeric_limits<float>::max();

        for (const Entity& e : entities) {
            if (!e.active) continue;

            Vec2 s;
            if (!worldToScreen(vp, e.head, viewW, viewH, s)) continue;

            const float dx = s.x - center.x;
            const float dy = s.y - center.y;
            const float dist = std::sqrt(dx * dx + dy * dy);

            const bool  sticky = (e.id == targetId_);
            const float radius = cfg_.fovRadiusPx + (sticky ? cfg_.stickyBonusPx : 0.f);
            if (dist > radius) continue;

            const float score = dist - (sticky ? cfg_.stickyBonusPx : 0.f);
            if (score < bestScore) {
                bestScore  = score;
                bestId     = e.id;
                bestOffset = { dx, dy };
            }
        }

        targetId_ = bestId;
        if (bestId < 0) return {};

        // Exponential smoothing, independent of frame rate.
        const float alpha = 1.0f - std::exp(-cfg_.smoothRate * std::fmax(dt, 0.f));
        Vec2 delta{ bestOffset.x * alpha, bestOffset.y * alpha };

        if (cfg_.maxStepPx > 0.f) {
            const float mag = std::sqrt(delta.x * delta.x + delta.y * delta.y);
            if (mag > cfg_.maxStepPx) {
                const float k = cfg_.maxStepPx / mag;
                delta.x *= k;
                delta.y *= k;
            }
        }
        return delta;
    }

private:
    Config  cfg_;
    int32_t targetId_ = -1;
};

} // namespace aim
